/*
 * Moonlight Sonata player v8 (VGA), 1x1 tile: Beethoven, Sonata op. 27 no. 2, 3rd movement
 * (Presto agitato), bars 1-37 and the final cadence (bars 200-201), 61 s, 388 notes of the
 * right hand top line (score: Craig Sapp, Humdrum sonata14-3.krn). Tables generated by
 * full-mvt/gen_rtl.py, then made flat for routing (full-mvt/make_v8s.py).
 *
 * The song is kept in 2 tables, read in order:
 *   phrase : 156 beats, each (cell, root pitch).
 *   cells  : 53 different beats (4 sixteenths). Each sixteenth is a code: 0..29 = semitones above
 *            the beat root (a new note), 30 = hold the note, 31 = rest.
 * Sound (v7-like): a triangle wave at the exact note period (the tone counter counts up and down,
 * so it is the triangle), scaled per octave, times a piano-like envelope (3 dB steps, decay about
 * one step a sixteenth, quick release in rests), as a 1-bit first-order sigma-delta on every clock.
 *
 * 25.175 MHz clock (VGA). The player steps at clk/252 = 99.9 kHz (clk/100 with ui[5], viewer);
 * ui[6] = 1 steps on every clock (for a 100 kHz board clock, and for fast simulation).
 *   uo_out      TinyVGA PMOD {hsync, B0, G0, R0, vsync, B1, G1, R1}, from flip-flops
 *   uio_out[0]  audio, uio_out[7] audio (audio PMOD), from the sigma-delta flip-flop
 *   ui_in[0]    half speed, ui_in[3] loop off, ui_in[5] viewer (clk / 100), ui_in[6] fast step
 *               (100 kHz clock), ui_in[7] pause
 */
`default_nettype none

module tt_um_mpriede_moonlight_sonata_player_vga (
    input  wire [7:0] ui_in,
    output wire [7:0] uo_out,
    input  wire [7:0] uio_in,
    output wire [7:0] uio_out,
    output wire [7:0] uio_oe,
    input  wire       ena,
    input  wire       clk,
    input  wire       rst_n
);
    // ---- switches (1 flip-flop each, only the bits that are used: slow hand switches) ----
    reg [6:0] sw;
    always @(posedge clk) begin
        if (!rst_n) sw <= 7'd0;       // defined from the first reset clock (gate level)
        else        sw <= {ui_in[7:5], ui_in[3:0]};
    end
    wire [1:0] speed  = sw[1:0];
    wire       loop   = ~sw[3];
    wire       viewer = sw[4];        // ui[5]: step on 1 clock in 100 (for a slow simulator)
    wire       fast   = sw[5];
    wire       play   = ~sw[6];

    // ---- step enable: clk / 252 = 99.9 kHz, clk / 100 with ui[5] (the Vulkos VGA viewer
    // simulates at 20-64 % of 25.175 MHz, so the song is 2.52x faster and higher there and
    // sounds near right), or every clock in fast mode ------------------------------------
    reg [7:0] pre;
    wire pre_last = viewer ? (pre == 8'd99) : (pre == 8'd251);
    always @(posedge clk) begin
        if (!rst_n || pre_last) pre <= 8'd0;
        else                    pre <= pre + 8'd1;
    end
    wire ce = fast | pre_last;

    // ---- tempo: ticks in one sixteenth (MM154) ---------------------------------------
    reg [14:0] six_last;
    always @(*) begin
        six_last = speed[0] ? 15'd19479 : 15'd9739;   // ui[0]: half speed
    end

    // ---- sequencer state ---------------------------------------------------------------
    reg [7:0]  k;          // beat entry, 0..155
    reg [1:0]  slot;       // sixteenth inside the beat
    reg [14:0] tick;
    reg        active, play_last, newslot;
    wire [7:0] addr = k;

    wire [11:0] ph_word;
    song_phrase u_phrase (.a(addr), .d(ph_word));   // 156 x 12 = 1872 bits

    wire [5:0]   cell_id = ph_word[5:0];
    wire [5:0]        root    = ph_word[11:6];

    wire [19:0] cell_word;
    song_cells u_cells (.a(cell_id), .d(cell_word));   // 53 x 20 = 1060 bits

    reg [4:0] code;
    always @(*) begin
        case (slot)
            2'd0: code = cell_word[4:0];
            2'd1: code = cell_word[9:5];
            2'd2: code = cell_word[14:10];
            default: code = cell_word[19:15];
        endcase
    end
    wire is_hold = (code == 5'd30);
    wire is_rest = (code == 5'd31);
    wire [5:0] new_pitch = root + {1'b0, code};

    wire six_done = (tick == 15'd0);
    wire last_k = (k == 8'd155);
    always @(posedge clk) begin
        if (!rst_n) begin
            tick <= 15'd9739; slot <= 2'd0; k <= 8'd0;   // constant: defined after 1 reset clock (sw is reset too)
            active <= 1'b1; play_last <= 1'b0; newslot <= 1'b1;
        end else if (ce) begin
            play_last <= play;
            newslot <= 1'b0;
            if (!active && play && !play_last) begin
                tick <= six_last; slot <= 2'd0; k <= 8'd0;
                active <= 1'b1; newslot <= 1'b1;
            end else if (play && active) begin
                if (!six_done) tick <= tick - 15'd1;
                else begin
                    tick <= six_last; newslot <= 1'b1; slot <= slot + 2'd1;
                    if (slot == 2'd3) begin
                        k <= last_k ? 8'd0 : k + 8'd1;
                        if (last_k) active <= loop;
                    end
                end
            end
        end
    end

    // ---- note, envelope, tone (v7 sound) ---------------------------------------------
    wire playing = play & active;
    wire start_note = ce & newslot & playing & ~is_hold & ~is_rest;
    reg [5:0] pitch;
    reg       resting;
    always @(posedge clk) begin
        if (!rst_n) begin pitch <= 6'd0; resting <= 1'b1; end
        else if (ce & newslot & playing & ~is_hold) begin
            resting <= is_rest;
            if (!is_rest) pitch <= new_pitch;
        end
    end

    wire [10:0] pitch_word;
    song_pitch u_pitch (.a(pitch), .d(pitch_word));   // 45 x 11 = 495 bits
    wire [8:0] half_m1 = pitch_word[8:0];   // half period - 1
    wire [1:0] sh = pitch_word[10:9];   // octave scale of the triangle

    // tone_count counts 0 -> half-1 (tone low), then half-1 -> 0 (tone high): a triangle
    // with the exact note period, made by the tone counter itself.
    reg [8:0] tone_count;
    reg             tone;
    always @(posedge clk) begin
        if (!rst_n || start_note) begin
            tone_count <= 0; tone <= 1'b0;
        end else if (ce) begin
            if (!tone) begin
                if (tone_count == half_m1) tone <= 1'b1;
                else tone_count <= tone_count + 1'b1;
            end else begin
                if (tone_count == 0) tone <= 1'b0;
                else tone_count <= tone_count - 1'b1;
            end
        end
    end
    // tri8 = (tone_count << sh) / 2 (peak 120..241), then >> att/2: one shifter
    wire [3:0] shr = 4'd4 - {2'b0, sh} + {1'b0, att[3:1]};

    // Envelope (as v7): att = attenuation in about 3 dB steps, 15 = silent. A note starts at
    // att 0 and decays one step each time tick[12:0] is all ones (about once a sixteenth),
    // like a piano string, down to att 3 (-9 dB peak / 8): a 1-bit output at a 100 kHz board clock
    // buzzes at very low levels, so the note does not sink below that. A rest, pause or the end
    // releases one step every 16 ticks (silent in about 2 ms). After a pause the note stays silent
    // until the next note starts (no click: v7 finding 3, att <= !sounding ? 15 : ...).
    reg [3:0] att;
    always @(posedge clk) begin
        if (!rst_n) att <= 4'd15;
        else if (start_note) att <= 4'd0;
        else if (ce) begin
            if (!playing || resting) begin
                if (tone_count[3:0] == 4'hF && att != 4'd15) att <= att + 4'd1;
            end else if (tick[12:0] == 13'h1FFF && att < 4'd3) att <= att + 4'd1;
        end
    end
    wire [3:0] amp = ~att;           // loudness, for the bar and the tests (0 = silent)

    // Loudness: tri8 x 2^-(att/2), with 3/4 for the odd steps (-2.5 dB).
    wire [11:0] tri_w = {tone_count, 3'b000} >> shr;
    wire [7:0] tri_sh = tri_w[7:0];
    wire [7:0] sample = (att == 4'd15) ? 8'd0 : (att[0] ? tri_sh - (tri_sh >> 2) : tri_sh);

    // ---- 1st-order sigma-delta: carry of an 8-bit accumulator, on every clock --------------
    reg [8:0] sd_acc;
    always @(posedge clk) begin
        if (!rst_n) sd_acc <= 9'd0;
        else        sd_acc <= {1'b0, sd_acc[7:0]} + {1'b0, sample};
    end
    wire speaker = sd_acc[8];

    // ---- screen: bar height = pitch + envelope -----------------------------------------
    wire [7:0] level = playing ? {1'b0, amp, 3'b000} : 8'd0;   // bar = loudness: jumps on each note, then sinks
    wire       hsync, vsync, video_on, frame;
    wire [9:0] x, y;
    wire [5:0] rgb;
    vga_sync vga (.clk(clk), .rst_n(rst_n), .hsync(hsync), .vsync(vsync), .active(video_on), .x(x), .y(y), .frame(frame));
    vga_level_bar bar (.x(x), .y(y), .active(video_on), .level(level), .rgb(rgb));

    // outputs from flip-flops (no comparator glitch on a pin)
    reg [7:0] uo_q;
    always @(posedge clk) uo_q <= {hsync, rgb[0], rgb[2], rgb[4], vsync, rgb[1], rgb[3], rgb[5]};
    assign uo_out  = uo_q;
    assign uio_out = {speaker, 6'b0, speaker};
    assign uio_oe  = 8'h81;

    wire _unused_ok = &{ena, uio_in, frame, sw[1], sw[2]};
endmodule
// The VGA shell, given. Two modules:
//   vga_sync       makes the 640x480 at 60 Hz timing from a 25 MHz clock and says which pixel is being drawn.
//   vga_level_bar  draws a vertical bar whose height is an 8 bit level, for the tracks that show a number.
// You do not edit this file.

module vga_sync (
    input  wire       clk,
    input  wire       rst_n,
    output wire       hsync,    // active low
    output wire       vsync,    // active low
    output wire       active,   // high inside the 640x480 picture
    output wire [9:0] x,        // pixel column, 0 to 639 when active
    output wire [9:0] y,        // pixel row, 0 to 479 when active
    output wire       frame     // one clock pulse per picture, at the start of the blanking
);
    reg [9:0] hc, vc;

    always @(posedge clk) begin
        if (!rst_n) begin
            hc <= 10'd0;
            vc <= 10'd0;
        end else if (hc == 10'd799) begin
            hc <= 10'd0;
            vc <= (vc == 10'd524) ? 10'd0 : vc + 10'd1;
        end else begin
            hc <= hc + 10'd1;
        end
    end

    assign x      = hc;
    assign y      = vc;
    assign active = (hc < 10'd640) && (vc < 10'd480);
    assign hsync  = ~((hc >= 10'd656) && (hc < 10'd752));
    assign vsync  = ~((vc >= 10'd490) && (vc < 10'd492));
    assign frame  = (hc == 10'd640) && (vc == 10'd480);
endmodule

module vga_level_bar (
    input  wire [9:0] x,
    input  wire [9:0] y,
    input  wire       active,
    input  wire [7:0] level,
    output wire [5:0] rgb       // {R[1:0], G[1:0], B[1:0]}
);
    wire [9:0] from_bottom = 10'd479 - y;
    wire       in_bar      = (x >= 10'd256) && (x < 10'd384);
    wire       lit         = in_bar && ({1'b0, level, 1'b0} > from_bottom);

    assign rgb = !active ? 6'b000000 : lit ? 6'b001100 : 6'b000001;
endmodule



